let passed = 0;let failed = 0;

function assert(condition, msg, details) {
  if (condition) {
    console.log(`  ✅ ${msg}`);
    passed++;
  } else {
    console.error(`  ❌ ${msg}${details ? ` — ${details}` : ''}`);
    failed++;
  }
}

function assertRange(value, min, max, label) {
  assert(value >= min && value <= max, `${label}: ${(value * 100).toFixed(1)}% (expected ${(min * 100).toFixed(0)}-${(max * 100).toFixed(0)}%)`);
}

