function testConstraintScoring() {
  console.log('\n═══ CONSTRAINT SCORING ═══');
  const job = makeJob();

  // 1. Perfect location match
  console.log('\n📍 Location Tests:');
  const perfectLoc = makeCandidate();
  const perfectLocScore = (0, _matchingUtils.calculateConstraintScore)(job, perfectLoc);
  assertRange(perfectLocScore, 0.8, 1.0, 'Same city (Geneva)');

  // 2. Same country, different city
  const sameCountry = makeCandidate({
    residence: { country: 'switzerland', city: 'Zurich' },
    preferences: { ...makeCandidate().preferences, preferred_locations: [{ country: 'switzerland', city: 'Zurich' }] }
  });
  const sameCountryScore = (0, _matchingUtils.calculateConstraintScore)(job, sameCountry);
  assertRange(sameCountryScore, 0.55, 0.85, 'Same country (Switzerland), different city');

  // 3. EU but different country
  const euCandidate = makeCandidate({
    residence: { country: 'italy', city: 'Milan' },
    preferences: { ...makeCandidate().preferences, preferred_locations: [{ country: 'italy', city: 'Milan' }] }
  });
  const euScore = (0, _matchingUtils.calculateConstraintScore)(job, euCandidate);
  assertRange(euScore, 0.5, 0.75, 'EU country (Italy)');
  assert(euScore < sameCountryScore, 'EU candidate should rank below same-country candidate');

  // 4. Non-EU different country
  const farCandidate = makeCandidate({
    residence: { country: 'brazil', city: 'São Paulo' },
    preferences: { ...makeCandidate().preferences, preferred_locations: [{ country: 'brazil', city: 'São Paulo' }] }
  });
  const farScore = (0, _matchingUtils.calculateConstraintScore)(job, farCandidate);
  assertRange(farScore, 0.4, 0.65, 'Non-EU country (Brazil)');
  assert(farScore < euScore, 'Non-EU should rank below EU candidate');

  // 5. Remote policy tests
  console.log('\n🏠 Remote Policy Tests:');
  const remoteJob = makeJob({ constraints: { ...makeJob().constraints, remote: 'full_remote' } });
  const remoteFarScore = (0, _matchingUtils.calculateConstraintScore)(remoteJob, farCandidate);
  assert(remoteFarScore > farScore, `Remote job should boost score for far candidate: ${(remoteFarScore * 100).toFixed(1)}% > ${(farScore * 100).toFixed(1)}%`);

  // 6. Contract type tests
  console.log('\n📝 Contract Type Tests:');
  const partTimeCandidate = makeCandidate({
    preferences: { ...makeCandidate().preferences, desired_contract_types: ['part_time'] }
  });
  const contractMismatch = (0, _matchingUtils.calculateConstraintScore)(job, partTimeCandidate);
  const contractMatch = (0, _matchingUtils.calculateConstraintScore)(job, makeCandidate());
  assert(contractMatch > contractMismatch, `Full-time match > Part-time mismatch: ${(contractMatch * 100).toFixed(1)}% > ${(contractMismatch * 100).toFixed(1)}%`);

  // 7. Salary tests
  console.log('\n💰 Salary Tests:');
  const highSalaryCandidate = makeCandidate({
    preferences: { ...makeCandidate().preferences, salary_eur: { min: 150000, flexibility: false } }
  });
  const salaryMismatch = (0, _matchingUtils.calculateConstraintScore)(job, highSalaryCandidate);
  assert(contractMatch > salaryMismatch, `Normal salary > High salary mismatch: ${(contractMatch * 100).toFixed(1)}% > ${(salaryMismatch * 100).toFixed(1)}%`);
}

function testFullRanking() {
  console.log('\n\n═══ FULL 7-PILLAR RANKING ═══');
  const job = makeJob();

  // 1. Perfect match
  console.log('\n🏆 Perfect Match:');
  const perfect = makeCandidate();
  const perfectScore = (0, _matchingUtils.calculateMatchScore)(job, perfect);
  assertRange(perfectScore.finalScore, 0.7, 1.0, 'Perfect match overall');
  assertRange(perfectScore.semanticScore, 0.9, 1.0, 'Semantic (identical embeddings)');
  assertRange(perfectScore.constraintScore, 0.8, 1.0, 'Constraints');
  assertRange(perfectScore.educationScore, 0.5, 1.0, 'Education (MSc at EPFL)');
  assertRange(perfectScore.careerPrestigeScore, 0.5, 1.0, 'Career Prestige (Google)');

  // 2. Good match — different city but same skills
  console.log('\n🥈 Good Match (different city):');
  const goodMatch = makeCandidate({
    id: 'cand_good',
    residence: { country: 'switzerland', city: 'Zurich' },
    preferences: { ...makeCandidate().preferences, preferred_locations: [{ country: 'switzerland', city: 'Zurich' }] },
    embedding_vector: [0.75, 0.55, 0.35, 0.2, 0.1]
  });
  const goodScore = (0, _matchingUtils.calculateMatchScore)(job, goodMatch);
  assertRange(goodScore.finalScore, 0.65, 0.97, 'Good match overall');
  assert(goodScore.finalScore <= perfectScore.finalScore + 0.001, `Good <= Perfect when constraints are unweighted: ${(goodScore.finalScore * 100).toFixed(1)}% <= ${(perfectScore.finalScore * 100).toFixed(1)}%`);

  // 3. Mediocre match — different country, partial skills
  console.log('\n🥉 Mediocre Match (Italy, partial skills):');
  const mediocre = makeCandidate({
    id: 'cand_mediocre',
    residence: { country: 'italy', city: 'Milan' },
    preferences: { ...makeCandidate().preferences, preferred_locations: [{ country: 'italy', city: 'Milan' }] },
    skills: [{ skill_name: 'React', level: 7, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    it_skills: [],
    total_years_experience: 4,
    current_seniority_level: 'mid',
    embedding_vector: [0.5, 0.4, 0.3, 0.1, 0.0],
    education: [
    { degree_level: 'BSc', major: 'Computer Science', institution: 'University of Milan', currently_pursuing: false, from: '2014', to: '2017' }],

    experiences: [
    { role: 'Developer', company: 'LocalStartup', location: { country: 'italy', city: 'Milan' }, from: '2017-01', to: 'present', is_current_position: true }]

  });
  const mediocreScore = (0, _matchingUtils.calculateMatchScore)(job, mediocre);
  assertRange(mediocreScore.finalScore, 0.4, 0.75, 'Mediocre match overall');
  assert(mediocreScore.finalScore < goodScore.finalScore, `Mediocre < Good: ${(mediocreScore.finalScore * 100).toFixed(1)}% < ${(goodScore.finalScore * 100).toFixed(1)}%`);

  // 4. Poor match — completely different
  console.log('\n❌ Poor Match (Brazil, marketing, no skills):');
  const poor = makeCandidate({
    id: 'cand_poor',
    residence: { country: 'brazil', city: 'São Paulo' },
    preferences: {
      remote: 'full_remote',
      preferred_locations: [{ country: 'brazil' }],
      desired_contract_types: ['part_time'],
      salary_eur: { min: 150000, flexibility: false }
    },
    skills: [{ skill_name: 'Marketing Strategy', level: 8, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    it_skills: [{ skill_name: 'Excel', level: 6, rank: 1, level_source: 'cv_only', level_confidence: 'low' }],
    soft_skills: [],
    summary_text: 'Marketing manager with experience in brand strategy.',
    current_job_function: 'marketing',
    current_seniority_level: 'mid',
    total_years_experience: 3,
    embedding_vector: [0.1, 0.9, 0.8, 0.7, 0.6],
    education: [
    { degree_level: 'HSD', major: 'General Studies', institution: 'Local High School', currently_pursuing: false, from: '2010', to: '2014' }],

    experiences: [
    { role: 'Marketing Manager', company: 'SmallAgency', location: { country: 'brazil' }, from: '2018-01', to: 'present', is_current_position: true }]

  });
  const poorScore = (0, _matchingUtils.calculateMatchScore)(job, poor);
  assertRange(poorScore.finalScore, 0.04, 0.35, 'Poor match overall');
  assert(poorScore.finalScore < mediocreScore.finalScore, `Poor < Mediocre: ${(poorScore.finalScore * 100).toFixed(1)}% < ${(mediocreScore.finalScore * 100).toFixed(1)}%`);

  // 5. Verify ranking order
  console.log('\n📊 Final Ranking Order:');
  const allScores = [
  { name: 'Perfect', score: perfectScore.finalScore },
  { name: 'Good', score: goodScore.finalScore },
  { name: 'Mediocre', score: mediocreScore.finalScore },
  { name: 'Poor', score: poorScore.finalScore }].
  sort((a, b) => b.score - a.score);

  console.log('  Ranking:');
  allScores.forEach((s, i) => console.log(`    ${i + 1}. ${s.name}: ${(s.score * 100).toFixed(1)}%`));

  assert(allScores[0].name === 'Perfect', 'Rank 1 should be Perfect match');
  assert(allScores[1].name === 'Good', 'Rank 2 should be Good match');
  assert(allScores[2].name === 'Mediocre', 'Rank 3 should be Mediocre match');
  assert(allScores[3].name === 'Poor', 'Rank 4 should be Poor match');

  const spread = allScores[0].score - allScores[allScores.length - 1].score;
  assert(spread > 0.25, `Score spread should be > 25%: ${(spread * 100).toFixed(1)}%`);
}

function testFuzzySkillMatching() {
  console.log('\n\n═══ FUZZY SKILL MATCHING ═══');
  const job = makeJob();

  // 1. Synonym match: "JS" should match "JavaScript" requirement if job lists it
  console.log('\n🔗 Synonym Matching:');
  const jsJob = makeJob({
    skills: [{ skill_name: 'JavaScript', level: 8, must: true }],
    it_skills: []
  });
  const jsCand = makeCandidate({
    skills: [{ skill_name: 'JS', level: 8, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    it_skills: []
  });
  const jsScore = (0, _matchingUtils.calculateMatchScore)(jsJob, jsCand);
  assert(jsScore.hardSkillsScore > 0.5, `"JS" should match "JavaScript": hard skills = ${(jsScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 2. "ML" should match "Machine Learning"
  const mlJob = makeJob({
    skills: [{ skill_name: 'Machine Learning', level: 7, must: true }],
    it_skills: []
  });
  const mlCand = makeCandidate({
    skills: [{ skill_name: 'ML', level: 7, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    it_skills: []
  });
  const mlScore = (0, _matchingUtils.calculateMatchScore)(mlJob, mlCand);
  assert(mlScore.hardSkillsScore > 0.5, `"ML" should match "Machine Learning": hard skills = ${(mlScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 3. "React.js" should match "React"
  const reactjsCand = makeCandidate({
    skills: [{ skill_name: 'React.js', level: 9, rank: 1, level_source: 'cv_only', level_confidence: 'high' }],
    it_skills: []
  });
  const reactScore = (0, _matchingUtils.calculateMatchScore)(makeJob({
    skills: [{ skill_name: 'React', level: 8, must: true }],
    it_skills: []
  }), reactjsCand);
  assert(reactScore.hardSkillsScore > 0.5, `"React.js" should match "React": hard skills = ${(reactScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 4. "Java" should NOT match "JavaScript" (regression test)
  console.log('\n🚫 False Positive Prevention:');
  const javaCand = makeCandidate({
    skills: [{ skill_name: 'Java', level: 9, rank: 1, level_source: 'cv_only', level_confidence: 'high' }],
    it_skills: []
  });
  const javaForJsScore = (0, _matchingUtils.calculateMatchScore)(jsJob, javaCand);
  assert(javaForJsScore.hardSkillsScore < 0.5, `"Java" should NOT match "JavaScript": hard skills = ${(javaForJsScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 5. "R" should NOT match "React"
  const rCand = makeCandidate({
    skills: [{ skill_name: 'R', level: 9, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    it_skills: []
  });
  const rForReactScore = (0, _matchingUtils.calculateMatchScore)(makeJob({
    skills: [{ skill_name: 'React', level: 8, must: true }],
    it_skills: []
  }), rCand);
  assert(rForReactScore.hardSkillsScore < 0.5, `"R" should NOT match "React": hard skills = ${(rForReactScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 6. Soft skill synonym: "Problem Solving" should match "Analytical Thinking"
  // 7. "AWS" should match "Amazon Web Services"
  console.log('\n☁️ Abbreviation Matching:');
  const awsJob = makeJob({
    it_skills: [{ skill_name: 'Amazon Web Services', level: 7, must: true }],
    skills: []
  });
  const awsCand = makeCandidate({
    it_skills: [{ skill_name: 'AWS', level: 7, rank: 1, level_source: 'cv_only', level_confidence: 'medium' }],
    skills: []
  });
  const awsScore = (0, _matchingUtils.calculateMatchScore)(awsJob, awsCand);
  assert(awsScore.hardSkillsScore > 0.5, `"AWS" should match "Amazon Web Services": hard skills = ${(awsScore.hardSkillsScore * 100).toFixed(1)}%`);

  // 8. Chat-validated high-confidence skill should beat low-confidence CV-only evidence
  console.log('\n🧾 Skill Evidence Weighting:');
  const evidenceJob = makeJob({
    skills: [{ skill_name: 'React', level: 8, must: true }],
    it_skills: []
  });
  const lowEvidenceCand = makeCandidate({
    skills: [{ skill_name: 'React', level: 8, rank: 1, level_source: 'cv_only', level_confidence: 'low' }],
    it_skills: []
  });
  const highEvidenceCand = makeCandidate({
    skills: [{ skill_name: 'React', level: 8, rank: 1, level_source: 'chat_validated', level_confidence: 'high' }],
    it_skills: []
  });
  const lowEvidenceScore = (0, _matchingUtils.calculateMatchScore)(evidenceJob, lowEvidenceCand);
  const highEvidenceScore = (0, _matchingUtils.calculateMatchScore)(evidenceJob, highEvidenceCand);
  assert(highEvidenceScore.hardSkillsScore > lowEvidenceScore.hardSkillsScore,
  `Chat-validated high-confidence skill (${(highEvidenceScore.hardSkillsScore * 100).toFixed(1)}%) > low-confidence CV-only (${(lowEvidenceScore.hardSkillsScore * 100).toFixed(1)}%)`);
}

